// putCanon writes canonical body.
func putCanon(b *bin.Buffer, l Layer, s Sym, v bin.Object) error {
	id, ok := Ctor(l, s)
	if !ok {
		return fmt.Errorf("%w: %s in layer %d", ErrAbsent, SymName(s), l)
	}
	b.PutID(id)
	e, ok := v.(bin.BareEncoder)
	if !ok {
		return fmt.Errorf("%w: %s", ErrNoPlan, SymName(s))
	}
	return e.EncodeBare(b)
}

// getCanon decodes canonical body.
func getCanon(b *bin.Buffer, l Layer, s Sym) (bin.Object, error) {
	v := newSym(s)
	if v == nil {
		return nil, fmt.Errorf("%w: %s", ErrNoPlan, SymName(s))
	}
	if _, ok := Ctor(l, s); !ok {
		return nil, fmt.Errorf("%w: %s in layer %d", ErrAbsent, SymName(s), l)
	}
	d, ok := v.(bin.BareDecoder)
	if !ok {
		return nil, fmt.Errorf("%w: %s", ErrNoPlan, SymName(s))
	}
	if err := d.DecodeBare(b); err != nil {
		return nil, err
	}
	return v, nil
}
